(function (window, document) {
  'use strict';

  const iconText = { success: '✓', error: '×', warning: '!', info: 'i', question: '?' };
  let activeClose = null;

  function focusable(root) {
    return [...root.querySelectorAll('button:not([disabled]), a[href], input:not([disabled]), [tabindex]:not([tabindex="-1"])')];
  }

  function fire(options) {
    if (typeof options === 'string') options = { title: options };
    options = options || {};
    if (activeClose) activeClose(false, 'replaced');

    const previousFocus = document.activeElement;
    const container = document.createElement('div');
    container.className = 'swal2-container';
    container.setAttribute('role', options.showCancelButton ? 'alertdialog' : 'dialog');
    container.setAttribute('aria-modal', 'true');
    const popup = document.createElement('div');
    popup.className = 'swal2-popup';
    const type = iconText[options.icon] ? options.icon : 'info';
    const icon = document.createElement('div');
    icon.className = 'swal2-icon ' + type;
    icon.setAttribute('aria-hidden', 'true');
    icon.textContent = iconText[type];
    const title = document.createElement('h2');
    title.className = 'swal2-title';
    title.id = 'swal2-title-' + Date.now();
    title.textContent = options.title || 'Confirm action';
    popup.setAttribute('aria-labelledby', title.id);
    const content = document.createElement('div');
    content.className = 'swal2-html-container';
    content.id = 'swal2-content-' + Date.now();
    content.textContent = options.text || '';
    popup.setAttribute('aria-describedby', content.id);
    const actions = document.createElement('div');
    actions.className = 'swal2-actions';
    const confirm = document.createElement('button');
    confirm.type = 'button';
    confirm.className = 'swal2-confirm';
    confirm.textContent = options.confirmButtonText || 'OK';
    actions.append(confirm);
    let cancel = null;
    if (options.showCancelButton) {
      cancel = document.createElement('button');
      cancel.type = 'button';
      cancel.className = 'swal2-cancel';
      cancel.textContent = options.cancelButtonText || 'Cancel';
      actions.append(cancel);
    }
    popup.append(icon, title, content, actions);
    container.append(popup);
    document.body.append(container);
    document.body.classList.add('swal2-shown');

    return new Promise((resolve) => {
      let settled = false;
      const done = (confirmed, reason = null) => {
        if (settled) return;
        settled = true;
        document.removeEventListener('keydown', onKeydown);
        container.remove();
        document.body.classList.remove('swal2-shown');
        activeClose = null;
        if (previousFocus && typeof previousFocus.focus === 'function' && previousFocus.isConnected) previousFocus.focus({ preventScroll: true });
        resolve({ isConfirmed: confirmed, isDismissed: !confirmed, dismiss: reason });
      };
      activeClose = done;
      const onKeydown = (event) => {
        if (event.key === 'Escape' && options.allowEscapeKey !== false) {
          event.preventDefault();
          done(false, 'esc');
          return;
        }
        if (event.key !== 'Tab') return;
        const elements = focusable(popup);
        if (!elements.length) return;
        const first = elements[0];
        const last = elements[elements.length - 1];
        if (event.shiftKey && document.activeElement === first) {
          event.preventDefault();
          last.focus();
        } else if (!event.shiftKey && document.activeElement === last) {
          event.preventDefault();
          first.focus();
        }
      };
      confirm.addEventListener('click', () => done(true));
      cancel?.addEventListener('click', () => done(false, 'cancel'));
      document.addEventListener('keydown', onKeydown);
      window.setTimeout(() => confirm.focus(), 0);
    });
  }

  function close() {
    if (activeClose) activeClose(false, 'close');
  }

  window.Swal = Object.freeze({ fire, close });
})(window, document);
